from intangible_assets.valuation_models import AssetType, ValuationDimension, ValuationQuestion, ValuationScoreGuide

def add_asset_type_with_guides(name, code, description, questions_data):
    asset_type, created = AssetType.objects.get_or_create(
        code=code,
        defaults={
            'name': name,
            'description': description,
            'is_active': True
        }
    )
    
    if not created:
        print(f"⚠️ {code} قبلاً وجود دارد - در حال بروزرسانی...")
        ValuationQuestion.objects.filter(asset_type=asset_type).delete()
    else:
        print(f"✅ {code} - {name} ایجاد شد")
    
    dimensions = {}
    for dim in ValuationDimension.objects.all():
        dimensions[dim.name] = dim
    
    added = 0
    for q_data in questions_data:
        question = ValuationQuestion.objects.create(
            asset_type=asset_type,
            dimension=dimensions[q_data['dim']],
            code=q_data['code'],
            question_text=q_data['text'],
            hint=q_data.get('hint', ''),
            order=added + 1
        )
        added += 1
        
        for sg in q_data.get('score_guides', []):
            ValuationScoreGuide.objects.create(
                question=question,
                score=sg['score'],
                condition=sg['condition'],
                evidence_required=sg.get('evidence', '')
            )
        
        print(f"  ✅ {q_data['code']}: {q_data['text'][:40]}...")
    
    print(f"  📌 {added} سوال اضافه شد")
    return asset_type


